# ═══════════════════════════════════════════════ LOAD SUDO USERS ═══════════════════════════════════════════════

SUDO_FILE = "sudo_users.json"



def load_sudo():

    global SUDO_USERS

    try:

        if os.path.exists(SUDO_FILE):

            with open(SUDO_FILE, "r") as f:

                data = json.load(f)

                SUDO_USERS = set(data.get("users", []))

    except:

        SUDO_USERS = set()



def save_sudo():

    try:

        with open(SUDO_FILE, "w") as f:

            json.dump({"users": list(SUDO_USERS)}, f)

    except:

        pass



load_sudo()



# ═══════════════════════════════════════════════ AUTHORIZATION DECORATOR ═══════════════════════════════════════════════

def only_sudo(func):

    async def wrapper(update: Update, context: ContextTypes.DEFAULT_TYPE):

        if not update.effective_user:

            return

        uid = update.effective_user.id

        if uid != OWNER_ID and uid not in SUDO_USERS:

            try:

                await update.message.reply_text(AUTHORIZATION_MSG)

            except:

                pass

            return

        return await func(update, context)

    return wrapper



def only_owner(func):

    async def wrapper(update: Update, context: ContextTypes.DEFAULT_TYPE):

        if not update.effective_user:

            return

        uid = update.effective_user.id

        if uid != OWNER_ID:

            try:

                await update.message.reply_text("🚫 ᴏɴʟʏ ꜱᴇʀᴠᴇʀ ᴏᴡɴᴇʀ ᴄᴀɴ ᴜꜱᴇ ᴛꜱ ꜱʜʏᴛ ¡! ")

            except:

                pass

            return

        return await func(update, context)

    return wrapper



# ═══════════════════════════════════════════════ SET PREFIX COMMAND ═══════════════════════════════════════════════

@only_owner

async def setprefix_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):

    global CURRENT_PREFIX

    if not context.args:

        await update.message.reply_text(
            f"Current prefix: `{CURRENT_PREFIX}`\n"
            f"Usage: {CURRENT_PREFIX}setprefix <new_prefix>",
            parse_mode="Markdown",
        )

        return

    new_prefix = context.args[0].strip()

    if not new_prefix:
        await update.message.reply_text("❌ Prefix cannot be empty.")
        return

    if len(new_prefix) > 3:

        await update.message.reply_text("❌ Prefix too long! Max 3 characters.")

        return

    old_prefix = CURRENT_PREFIX.lower()
    CURRENT_PREFIX = new_prefix
    new_prefix_lower = CURRENT_PREFIX.lower()
    for app in RUNNING_APPS:
        for handlers in app.handlers.values():
            for handler in handlers:
                if isinstance(handler, PrefixHandler):
                    command_names = (
                        command[len(old_prefix):]
                        for command in handler.commands
                        if command.startswith(old_prefix)
                    )
                    handler.commands = frozenset(
                        new_prefix_lower + command_name
                        for command_name in command_names
                    )

    await update.message.reply_text(f"✅ Prefix changed to: `{CURRENT_PREFIX}`", parse_mode="Markdown")



