# ═══════════════════════════════════════════════ SPAM COMMAND HANDLERS (FIXED) ═══════════════════════════════════════════════

async def spam_worker_with_counter(
    bot,
    chat_id: int,
    target: str,
    spam_type: int,
    counter_dict: Dict[int, int],
):
    """Run one of the script's existing message templates with per-chat pacing."""
    templates_by_type = {
        1: SPAM1_TEXTS,
        2: SPAM2_TEXTS,
        3: SPAM3_TEXTS,
        4: SPAM4_TEXTS,
    }
    templates = templates_by_type.get(spam_type)
    if not templates:
        logger.error("Unknown spam template type: %s", spam_type)
        return

    lock = spam_send_locks.setdefault(chat_id, asyncio.Lock())
    template_index = 0

    while True:
        try:
            template = templates[template_index % len(templates)]
            text = template.format(target=target)
            encoded_text = text.encode("utf-16-le")
            if len(encoded_text) // 2 > 4000:
                text = encoded_text[:8000].decode("utf-16-le", errors="ignore")
            async with lock:
                # Serialize the configured bots so they do not burst one chat.
                interval = max(float(GLOBAL_DELAY), 1.0)
                remaining = interval - (
                    time.monotonic() - spam_last_sent.get(chat_id, 0.0)
                )
                if remaining > 0:
                    await asyncio.sleep(remaining)
                try:
                    await bot.send_message(
                        chat_id=chat_id,
                        text=text,
                        parse_mode=None,
                    )
                except RetryAfter as exc:
                    spam_last_sent[chat_id] = time.monotonic()
                    await asyncio.sleep(max(float(exc.retry_after), 1.0))
                    continue
                spam_last_sent[chat_id] = time.monotonic()

            counter_dict[chat_id] = counter_dict.get(chat_id, 0) + 1
            template_index += 1
        except asyncio.CancelledError:
            raise
        except (Forbidden, BadRequest) as exc:
            logger.warning("Stopping message worker for chat %s: %s", chat_id, exc)
            return
        except (TimedOut, NetworkError):
            await asyncio.sleep(1.0)
        except Exception:
            logger.exception("Unexpected message worker error in chat %s", chat_id)
            await asyncio.sleep(1.0)

@only_sudo

async def godspam1_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):

    if not context.args:

        return await update.message.reply_text(
            f"⚠️ ᴜꜱᴇ: {CURRENT_PREFIX}godspam1 <text>"
        )

    text = " ".join(context.args)

    chat_id = update.message.chat_id

    

    if chat_id in spam_tasks:

        for task in spam_tasks[chat_id]:

            task.cancel()

        del spam_tasks[chat_id]

    

    spam_counters[chat_id] = 0

    tasks = [asyncio.create_task(spam_worker_with_counter(bot, chat_id, text, 1, spam_counters)) for bot in ALL_BOTS]

    spam_tasks[chat_id] = tasks

    ACTIVE_TASKS[chat_id] = "spam1"

    await update.message.reply_text(f"✅ ꜱᴘᴀᴍ1 ꜱᴛᴀʀᴛᴇᴅ ᴡɪᴛʜ {len(ALL_BOTS)} ʙᴏᴛꜱ!\nᴛᴀʀɢᴇᴛ: {text}\n⚡ ᴜʟᴛʀᴀ ꜱᴘᴇᴇᴅ")



