# ═══════════════════════════════════════════════ FORWARD SPAM COMMAND HANDLERS ═══════════════════════════════════════════════

# Add this new dictionary for forward spam tasks

fwdspam_tasks: Dict[int, List[asyncio.Task]] = {}

fwdspam_counters: Dict[int, int] = {}



@only_sudo

async def fwdspam_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):

    """Continuously forward the replied-to message as fast as possible with all bots."""

    message = update.effective_message

    source = message.reply_to_message if message else None

    if source is None:

        await message.reply_text("ʀᴇᴘʟʏ ᴛᴏ ᴀ ᴍꜱɢ")

        return



    chat_id = update.effective_chat.id

    

    # Stop any existing forward spam in this chat

    if chat_id in fwdspam_tasks:

        for task in fwdspam_tasks[chat_id]:

            task.cancel()

        del fwdspam_tasks[chat_id]

    

    # Reset counter

    fwdspam_counters[chat_id] = 0

    

    # Start forwarding tasks for all bots

    tasks = [asyncio.create_task(fwdspam_worker(bot, chat_id, source.chat_id, source.message_id, fwdspam_counters)) for bot in ALL_BOTS]

    fwdspam_tasks[chat_id] = tasks

    ACTIVE_TASKS[chat_id] = "fwdspam"

    

    await message.reply_text(

        f"✅ ꜰᴡᴅꜱᴘᴀᴍ ꜱᴛᴀʀᴛᴇᴅ ᴡɪᴛʜ {len(ALL_BOTS)} ʙᴏᴛꜱ!\n"

        f"⚡ ᴜʟᴛʀᴀ ꜱᴘᴇᴇᴅ - 0.0ꜱ ᴅᴇʟᴀʏ"

    )



async def fwdspam_worker(bot, chat_id, from_chat_id, message_id, counter_dict):

    """Worker that continuously forwards the same message."""

    while True:

        try:

            await bot.forward_message(

                chat_id=chat_id,

                from_chat_id=from_chat_id,

                message_id=message_id,

            )

            counter_dict[chat_id] = counter_dict.get(chat_id, 0) + 1

            await asyncio.sleep(0)  # Zero delay - maximum speed

        except asyncio.CancelledError:

            break

        except RetryAfter as e:

            await asyncio.sleep(e.retry_after)

        except (TimedOut, NetworkError) as e:

            # Brief pause on network errors, then retry

            await asyncio.sleep(0.01)

        except BadRequest as e:

            # If message can't be forwarded, break

            if "message to forward not found" in str(e):

                break

            await asyncio.sleep(0.01)

        except Forbidden:

            # Bot might be restricted, break

            break

        except Exception:

            # Catch-all for any other errors

            await asyncio.sleep(0.01)



@only_sudo

async def stopfwdspam_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):

    """Stop the forward spam in the current chat."""

    chat_id = update.effective_chat.id

    if chat_id in fwdspam_tasks:

        for task in fwdspam_tasks[chat_id]:

            task.cancel()

        del fwdspam_tasks[chat_id]

    if chat_id in ACTIVE_TASKS and ACTIVE_TASKS.get(chat_id) == "fwdspam":

        del ACTIVE_TASKS[chat_id]

    await update.message.reply_text("🛑 ꜰᴡᴅꜱᴘᴀᴍ ꜱᴛᴏᴘᴘᴇᴅ!")



