# ═══════════════════════════════════════════════ NC WORKER FUNCTIONS ═══════════════════════════════════════════════

async def godnc1_worker(bot, chat_id, base_text, counter_dict, bot_index):

    emoji_len = len(GODNC1_EMOJIS)

    word_len = len(GODNC1_WORDS)

    e_idx = random.randint(0, 1000) + bot_index * 100

    w_idx = random.randint(0, 1000) + bot_index * 100

    

    while True:

        try:

            emoji = GODNC1_EMOJIS[e_idx % emoji_len]

            word = GODNC1_WORDS[w_idx % word_len]

            raw_text = GODNC1_PATTERN.format(target=transform_nc_target(base_text), text=base_text, word=word, emoji=emoji)

            text = raw_text

            await bot.set_chat_title(chat_id, text)

            counter_dict[chat_id] = counter_dict.get(chat_id, 0) + 1

            e_idx += 1

            w_idx += 1

            await asyncio.sleep(0)

        except asyncio.CancelledError:

            break

        except RetryAfter as e:

            await asyncio.sleep(e.retry_after)

        except:

            await asyncio.sleep(0)



