@only_owner
async def auto_react_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    global AUTO_REACT_OWNER_MESSAGES, AUTO_REACT_BOT_MESSAGES

    if not context.args:
        state = "ON" if AUTO_REACT_OWNER_MESSAGES else "OFF"
        await update.message.reply_text(
            f"Auto-react is {state}. Usage: {CURRENT_PREFIX}autoreact on|off"
        )
        return

    option = context.args[0].strip().lower()
