@only_owner
async def set_reaction_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    global AUTO_REACTION

    if not context.args:
        await update.message.reply_text(
            f"Usage: {CURRENT_PREFIX}setreaction <emoji|custom:<emoji_id>>"
        )
        return

    value = " ".join(context.args).strip()
    if value.lower().startswith("custom:"):
        custom_emoji_id = value.split(":", 1)[1].strip()
        if not custom_emoji_id:
            await update.message.reply_text(
                f"Usage: {CURRENT_PREFIX}setreaction custom:<emoji_id>"
            )
            return
        AUTO_REACTION = ReactionTypeCustomEmoji(
            custom_emoji_id=custom_emoji_id
        )
        display_value = "custom emoji"
    else:
        AUTO_REACTION = ReactionTypeEmoji(emoji=value)
        display_value = value

    await update.message.reply_text(
        f"✅ Reaction updated to {display_value}."
    )


async def _apply_auto_actions_to_sent_result(bot, result):
    """React to and pin a message after this bot successfully sends it."""
    messages = result if isinstance(result, list) else [result]
    for message in messages:
        chat = getattr(message, "chat", None)
        message_id = getattr(message, "message_id", None)
        if (
            not chat
            or not message_id
            or chat.type not in ("group", "supergroup")
        ):
            continue

        if AUTO_REACT_BOT_MESSAGES:
            try:
                await bot.set_message_reaction(
                    chat_id=chat.id,
                    message_id=message_id,
                    reaction=[AUTO_REACTION],
                )
            except Exception as exc:
                logger.debug("Auto-reaction failed for bot message: %s", exc)

        if AUTO_PIN_BOT_MESSAGES:
            try:
                await bot.pin_chat_message(
                    chat_id=chat.id,
                    message_id=message_id,
                    disable_notification=True,
                )
            except Exception as exc:
                logger.debug("Auto-pin failed for bot message: %s", exc)


def _wrap_outbound_method(method):
    """Wrap a Bot API send method without changing its return value."""
    async def wrapped(self, *args, **kwargs):
        result = await method(self, *args, **kwargs)
        await _apply_auto_actions_to_sent_result(self, result)
        return result

    wrapped.__name__ = method.__name__
    wrapped.__doc__ = method.__doc__
    return wrapped


class AutoActionBot(ExtBot):
    """Bot subclass that reacts to and pins its own outgoing group messages."""


for _outbound_method_name in (
    "send_message",
    "send_photo",
    "send_sticker",
    "send_video",
    "send_document",
    "send_animation",
    "send_audio",
    "send_voice",
    "send_video_note",
    "send_location",
    "send_contact",
    "send_poll",
    "send_venue",
    "send_dice",
    "send_media_group",
    "forward_message",
):
    setattr(
        AutoActionBot,
        _outbound_method_name,
        _wrap_outbound_method(getattr(ExtBot, _outbound_method_name)),
    )


async def owner_message_actions_handler(
    update: Update,
    context: ContextTypes.DEFAULT_TYPE,
):
    """React to every owner message; let one bot pin it to avoid duplicate pins."""
    message = update.effective_message
    if (
        not message
        or not message.from_user
        or message.from_user.id != OWNER_ID
        or message.chat.type not in ("group", "supergroup")
    ):
        return

    if AUTO_REACT_OWNER_MESSAGES:
        try:
            await context.bot.set_message_reaction(
                chat_id=message.chat_id,
                message_id=message.message_id,
                reaction=[AUTO_REACTION],
            )
        except Exception as exc:
            logger.debug("Auto-reaction failed for owner message: %s", exc)

    if AUTO_PIN_OWNER_MESSAGES and context.bot is REPLY_BOT:
        try:
            await context.bot.pin_chat_message(
                chat_id=message.chat_id,
                message_id=message.message_id,
                disable_notification=True,
            )
        except Exception as exc:
            logger.debug("Auto-pin failed for owner message: %s", exc)


async def welcome_new_members_handler(
    update: Update,
    context: ContextTypes.DEFAULT_TYPE,
):
    """Send the configured welcome message once for each new group member."""
    message = update.effective_message
    if (
        not WELCOME_MESSAGE
        or not message
        or not message.new_chat_members
        or message.chat.type not in ("group", "supergroup")
    ):
        return
    if REPLY_BOT is not None and context.bot is not REPLY_BOT:
        return

    for member in message.new_chat_members:
        values = {
            "name": member.full_name,
            "first_name": member.first_name,
            "username": f"@{member.username}" if member.username else "",
            "chat_title": message.chat.title or "",
        }
        try:
            try:
                welcome_text = WELCOME_MESSAGE.format(**values)
            except (KeyError, ValueError):
                welcome_text = WELCOME_MESSAGE
            await context.bot.send_message(
                chat_id=message.chat_id,
                text=welcome_text,
            )
        except Exception as exc:
            logger.debug("Welcome message failed for new member: %s", exc)


